import sys

def process_spell():
    lines = sys.stdin.readlines()
    result = []
    current_line = ""
    for line in lines:
        stripped_line = line.rstrip('\n')
        if stripped_line.lstrip().startswith('#'):
            if current_line:
                result.append(current_line)
                current_line = ""
            result.append(stripped_line)
        else:
            current_line += ''.join(stripped_line.split())
    if current_line:
        result.append(current_line)
    for line in result:
        print(line)

process_spell()
